use super::*;

/// Every candidate record that holds MORE THAN ONE extractable pure leaf — the decomposition worklist —
/// ranked most-leaves-first, ties broken by id for determinism. A record with exactly one leaf is either
/// already single-method or a cohesive module whose one pure helper is not worth a split, so it is not a
/// "multi-method" finding.
pub fn worklist(impls: &[Value]) -> Vec<RecordLeaves> {
    let mut out: Vec<RecordLeaves> = impls
        .iter()
        .filter(|r| is_candidate_record(r))
        .filter_map(|r| {
            let id = r.get("id").and_then(Value::as_str)?.to_string();
            let code = r.get("code").and_then(Value::as_str).unwrap_or("");
            let tech = r.get("tech").and_then(Value::as_str).unwrap_or("");
            let names = extractable_leaves(code, tech);
            if names.len() <= 1 {
                return None;
            }
            // DEMOTE cohesive modules — the worklist is GENUINE independent-leaf collections only, so a
            // decomposition pass is never aimed at a module Decision 3 says to leave whole.
            if cohesion_reason(code, tech, &names).is_some() {
                return None;
            }
            Some(RecordLeaves { id, names })
        })
        .collect();
    out.sort_by(|a, b| b.names.len().cmp(&a.names.len()).then_with(|| a.id.cmp(&b.id)));
    out
}
